const SURFACES = new Set<LearnerSurface>(["web", "desktop", "mobile", "terminal"]);
const LIFECYCLES = new Set<DocumentLifecycle>(["draft", "streaming", "ready", "submitted", "completed", "failed", "cancelled"]);
const ACTION_TYPES = new Set<UiAction["type"]>(["submit-answer", "choose-option", "complete-goal-step", "rate-card", "save-artifact", "retry", "open-handoff"]);

function validRevision(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function validateUiDocumentNode(value: unknown): value is UiDocumentNode {
  if (!isRecord(value) || !isContractId(value.id) || typeof value.type !== "string") return false;
  switch (value.type) {
    case "markdown": return typeof value.markdown === "string";
    case "question": return typeof value.prompt === "string"
      && (value.choices === undefined || (Array.isArray(value.choices) && value.choices.every((choice) => typeof choice === "string")))
      && (value.multiSelect === undefined || typeof value.multiSelect === "boolean");
    case "quiz": return isContractId(value.quizId);
    case "goal": return isContractId(value.goalId);
    case "study-plan": case "artifact": return isContractId(value.artifactId);
    case "deck": return isContractId(value.deckId);
    case "image": return isContractId(value.artifactId) && typeof value.alt === "string";
    case "media": return isContractId(value.artifactId) && (value.kind === "animation" || value.kind === "audio" || value.kind === "video");
    case "handoff": return SURFACES.has(value.target as LearnerSurface) && typeof value.reason === "string" && isContractId(value.contextId);
    default: return false;
  }
}

export function validateUiDocument(value: unknown): value is UiDocument {
  if (!isRecord(value) || value.schemaVersion !== UI_CONTRACT_VERSION || !isContractId(value.id)
    || !validRevision(value.revision) || !LIFECYCLES.has(value.lifecycle as DocumentLifecycle)
    || !Array.isArray(value.supportedSurfaces) || value.supportedSurfaces.length === 0
    || !value.supportedSurfaces.every((surface) => SURFACES.has(surface as LearnerSurface))
    || new Set(value.supportedSurfaces).size !== value.supportedSurfaces.length
    || !Array.isArray(value.nodes) || !value.nodes.every(validateUiDocumentNode)
    || new Set(value.nodes.map((node) => node.id)).size !== value.nodes.length
    || !isContractTimestamp(value.createdAt) || !isContractTimestamp(value.updatedAt)) return false;
  return true;
}

export function validateUiAction(value: unknown): value is UiAction {
  if (!isRecord(value) || value.schemaVersion !== UI_CONTRACT_VERSION || !ACTION_TYPES.has(value.type as UiAction["type"])
    || !isContractId(value.documentId) || !validRevision(value.documentRevision) || !isContractId(value.idempotencyKey)) return false;
  const nodeAction = value.type !== "retry";
  if (nodeAction && !isContractId(value.nodeId)) return false;
  switch (value.type) {
    case "submit-answer": return typeof value.answer === "string" || (Array.isArray(value.answer) && value.answer.every((answer) => typeof answer === "string"));
    case "choose-option": return Array.isArray(value.optionIds) && value.optionIds.length > 0 && value.optionIds.every(isContractId);
    case "complete-goal-step": return isContractId(value.stepId);
    case "rate-card": return value.rating === 0 || value.rating === 1 || value.rating === 2 || value.rating === 3;
    case "save-artifact": case "retry": case "open-handoff": return true;
    default: return false;
  }
}

export function validateUiActionResult(value: unknown): value is UiActionResult {
  const retryAfterMs = isRecord(value) ? value.retryAfterMs : undefined;
  if (!isRecord(value) || value.schemaVersion !== UI_CONTRACT_VERSION || !isContractId(value.documentId)
    || !validRevision(value.documentRevision) || !isContractId(value.actionIdempotencyKey)
    || !(value.status === "accepted" || value.status === "completed" || value.status === "rejected" || value.status === "retryable")
    || !LIFECYCLES.has(value.documentLifecycle as DocumentLifecycle)
    || (value.message !== undefined && typeof value.message !== "string")
    || (retryAfterMs !== undefined && (typeof retryAfterMs !== "number" || !Number.isSafeInteger(retryAfterMs) || retryAfterMs < 0))) return false;
  return value.status !== "retryable" || retryAfterMs !== undefined;
}

/** A result is only applicable to the action/document revision it acknowledges. */
export function validateUiActionCorrelation(action: UiAction, result: UiActionResult): boolean {
  return action.schemaVersion === result.schemaVersion
    && action.documentId === result.documentId
    && action.documentRevision === result.documentRevision
    && action.idempotencyKey === result.actionIdempotencyKey;
}
