# 1
export type ArtifactKind =
  | "note"
  | "explanation"
  | "study-plan"
  | "lesson-map"
  | "quiz"
  | "deck"
  | "image"
  | "animation"
  | "verification"
  | "document"
  | "other";

export type ArtifactFormat = "markdown" | "mermaid" | "quiz" | "openui" | "image" | "video" | "json" | "text";

export interface LearnerArtifact {
  id: string;
  kind: ArtifactKind;
  format: ArtifactFormat;
  title: string;
  createdAt: string;
  updatedAt: string;
  content?: string;
  sourceSessionId?: string;
  sourceMessageId?: string;
  /** An attachment is a reference, never local file bytes or a workspace path. */
  attachment?: {
    id: string;
    mimeType: string;
    sizeBytes: number;
    remoteUrl?: string;
  };
}

export type GoalStepStatus = "not_started" | "in_progress" | "done";

export interface LearnerGoal {
  id: string;
  title: string;
  description: string;
  updatedAt: string;
  steps: Array<{
    id: string;
    title: string;
    status: GoalStepStatus;
    successCriteria: string[];
  }>;
}

export interface LearnerQuestionCheck {
  id: string;
  topic: string;
  question: string;
  answer: string;
  createdAt: string;
  score?: number;
  grading: "auto" | "model" | "pending";
  misconception?: string;
  sessionId?: string;
}

export interface LearnerQuizResult {
  id: string;
  topic: string;
  createdAt: string;
  score: number;
  totalQuestions: number;
  answers: Record<string, string>;
  partialCredits?: Record<string, number>;
  pendingGradeQuestionIds?: string[];
  sessionId?: string;
}

export interface Flashcard {
  id: string;
  front: string;
  back: string;
  tags: string[];
}

export interface FlashcardDeck {
  id: string;
  title: string;
  topic: string;
  createdAt: string;
  updatedAt: string;
  cards: Flashcard[];
}

export interface CardReviewRecord {
  id: string;
  deckId: string;
  cardId: string;
  rating: 0 | 1 | 2 | 3;
  appliedIntervalDays: number;
  easeAfter: number;
  createdAt: string;
  sessionId?: string;
}

export interface LearnerProfile {
  topicsExplored: string[];
  strengths: string[];
  weaknesses: string[];
  lastSessionAt?: string;
  sessionsCount: number;
}

const ARTIFACT_KINDS = new Set<ArtifactKind>([
  "note", "explanation", "study-plan", "lesson-map", "quiz", "deck", "image", "animation", "verification", "document", "other",
]);
const ARTIFACT_FORMATS = new Set<ArtifactFormat>(["markdown", "mermaid", "quiz", "openui", "image", "video", "json", "text"]);
const GOAL_STEP_STATUSES = new Set<GoalStepStatus>(["not_started", "in_progress", "done"]);

function isTimestamp(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0 && Number.isFinite(Date.parse(value));
}

function hasId(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

export function validateLearnerArtifact(value: unknown): value is LearnerArtifact {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const artifact = value as Partial<LearnerArtifact>;
  if (!hasId(artifact.id) || !ARTIFACT_KINDS.has(artifact.kind as ArtifactKind)
    || !ARTIFACT_FORMATS.has(artifact.format as ArtifactFormat)
    || typeof artifact.title !== "string" || !isTimestamp(artifact.createdAt) || !isTimestamp(artifact.updatedAt)
    || (artifact.content !== undefined && typeof artifact.content !== "string")
    || (artifact.sourceSessionId !== undefined && !hasId(artifact.sourceSessionId))
    || (artifact.sourceMessageId !== undefined && !hasId(artifact.sourceMessageId))) return false;
  if (!artifact.attachment) return true;
  const attachment = artifact.attachment;
  if (!hasId(attachment.id) || typeof attachment.mimeType !== "string" || !attachment.mimeType.trim()
    || typeof attachment.sizeBytes !== "number" || !Number.isSafeInteger(attachment.sizeBytes) || attachment.sizeBytes < 0) return false;
  if (attachment.remoteUrl !== undefined) {
    try {
      const url = new URL(attachment.remoteUrl);
      if (url.protocol !== "https:" && url.protocol !== "http:") return false;
    } catch { return false; }
  }
  return true;
}

export function validateLearnerGoal(value: unknown): value is LearnerGoal {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const goal = value as Partial<LearnerGoal>;
  if (!hasId(goal.id) || typeof goal.title !== "string" || typeof goal.description !== "string"
    || !isTimestamp(goal.updatedAt) || !Array.isArray(goal.steps)) return false;
  const ids = new Set<string>();
  return goal.steps.every((step) => {
    if (!step || typeof step !== "object" || ids.has(step.id) || !hasId(step.id)
      || typeof step.title !== "string" || !GOAL_STEP_STATUSES.has(step.status)
      || !Array.isArray(step.successCriteria) || !step.successCriteria.every((criterion) => typeof criterion === "string")) return false;
    ids.add(step.id);
    return true;
  });
}

export function validateLearnerQuestionCheck(value: unknown): value is LearnerQuestionCheck {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const check = value as Partial<LearnerQuestionCheck>;
  return hasId(check.id) && typeof check.topic === "string" && typeof check.question === "string"
    && typeof check.answer === "string" && isTimestamp(check.createdAt)
    && (check.score === undefined || (typeof check.score === "number" && Number.isFinite(check.score) && check.score >= 0 && check.score <= 1))
    && (check.grading === "auto" || check.grading === "model" || check.grading === "pending")
    && (check.misconception === undefined || typeof check.misconception === "string")
    && (check.sessionId === undefined || hasId(check.sessionId));
}

export function validateLearnerQuizResult(value: unknown): value is LearnerQuizResult {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const quiz = value as Partial<LearnerQuizResult>;
  if (!hasId(quiz.id) || typeof quiz.topic !== "string" || !isTimestamp(quiz.createdAt)
    || typeof quiz.totalQuestions !== "number" || !Number.isSafeInteger(quiz.totalQuestions) || quiz.totalQuestions < 1
    || typeof quiz.score !== "number" || !Number.isFinite(quiz.score) || quiz.score < 0 || quiz.score > quiz.totalQuestions
    || !quiz.answers || typeof quiz.answers !== "object" || Array.isArray(quiz.answers)
    || !Object.values(quiz.answers).every((answer) => typeof answer === "string")) return false;
  if (quiz.partialCredits && (!Object.values(quiz.partialCredits).every((credit) =>
    typeof credit === "number" && Number.isFinite(credit) && credit >= 0 && credit <= 1))) return false;
  return (quiz.pendingGradeQuestionIds === undefined || (Array.isArray(quiz.pendingGradeQuestionIds)
    && quiz.pendingGradeQuestionIds.every(hasId)))
    && (quiz.sessionId === undefined || hasId(quiz.sessionId));
}

export function validateFlashcardDeck(value: unknown): value is FlashcardDeck {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const deck = value as Partial<FlashcardDeck>;
  if (!hasId(deck.id) || typeof deck.title !== "string" || typeof deck.topic !== "string"
    || !isTimestamp(deck.createdAt) || !isTimestamp(deck.updatedAt) || !Array.isArray(deck.cards)) return false;
  const ids = new Set<string>();
  return deck.cards.every((card) => {
    if (!card || typeof card !== "object" || !hasId(card.id) || ids.has(card.id)
      || typeof card.front !== "string" || typeof card.back !== "string"
      || !Array.isArray(card.tags) || !card.tags.every((tag) => typeof tag === "string")) return false;
    ids.add(card.id);
    return true;
  });
}

export function validateCardReviewRecord(value: unknown): value is CardReviewRecord {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const review = value as Partial<CardReviewRecord>;
  return hasId(review.id) && hasId(review.deckId) && hasId(review.cardId)
    && (review.rating === 0 || review.rating === 1 || review.rating === 2 || review.rating === 3)
    && typeof review.appliedIntervalDays === "number" && Number.isFinite(review.appliedIntervalDays) && review.appliedIntervalDays >= 0
    && typeof review.easeAfter === "number" && Number.isFinite(review.easeAfter) && review.easeAfter >= 1
    && isTimestamp(review.createdAt)
    && (review.sessionId === undefined || hasId(review.sessionId));
}

export function validateLearnerProfile(value: unknown): value is LearnerProfile {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const profile = value as Partial<LearnerProfile>;
  return Array.isArray(profile.topicsExplored) && profile.topicsExplored.every((value) => typeof value === "string")
    && Array.isArray(profile.strengths) && profile.strengths.every((value) => typeof value === "string")
    && Array.isArray(profile.weaknesses) && profile.weaknesses.every((value) => typeof value === "string")
    && typeof profile.sessionsCount === "number" && Number.isSafeInteger(profile.sessionsCount) && profile.sessionsCount >= 0
    && (profile.lastSessionAt === undefined || isTimestamp(profile.lastSessionAt));
}

