# 1
import {
  assertVersionedEnvelope,
  ContractValidationError,
  LEARNER_CONTRACT_VERSION,
  PORTABLE_LEARNER_DATA_KIND,
  type VersionedEnvelope,
} from "./envelope.js";
import type {
  CardReviewRecord,
  FlashcardDeck,
  LearnerArtifact,
  LearnerGoal,
  LearnerProfile,
  LearnerQuestionCheck,
  LearnerQuizResult,
} from "./learning.js";
import {
  validateCardReviewRecord,
  validateFlashcardDeck,
  validateLearnerArtifact,
  validateLearnerGoal,
  validateLearnerProfile,
  validateLearnerQuestionCheck,
  validateLearnerQuizResult,
} from "./learning.js";
import { validateLearnerSession, type LearnerSession } from "./sessions.js";
import { codePointCompare, hasOnlyKeys, hasUniqueIds, isContractId, isContractTimestamp } from "./validation.js";

export interface PortableLearnerData {
  generatedAt: string;
  sessions: LearnerSession[];
  artifacts: LearnerArtifact[];
  goals: LearnerGoal[];
  questionChecks: LearnerQuestionCheck[];
  quizResults: LearnerQuizResult[];
  decks: FlashcardDeck[];
  cardReviews: CardReviewRecord[];
  learnerProfile: LearnerProfile;
}

export type PortableLearnerEnvelope = VersionedEnvelope<PortableLearnerData>;

const FORBIDDEN_PORTABLE_KEY_PARTS = [
  "apikey", "apikeys", "oauthcredentials", "refreshtoken", "accesstoken", "idtoken", "authtoken",
  "sessiontoken", "clientsecret", "password", "cookie", "secret", "token",
  "dpop", "dpopkey", "dpopprivatekey", "assertion", "assertionkey", "assertionprivatekey",
  "privatekey", "credentials", "authorization", "authheader", "bearertoken", "providerkey",
  "workspacefiles", "workspacefilecontent", "localworkspacefiles", "localworkspacefilecontent",
  "workspacesnapshot", "sandboxfiles", "sandboxfilecontent",
] as const;
const PORTABLE_DATA_KEYS = new Set([
  "generatedAt", "sessions", "artifacts", "goals", "questionChecks", "quizResults", "decks", "cardReviews", "learnerProfile",
]);
const SECRET_VALUE_PATTERNS = [
  /-----BEGIN(?: [A-Z]+)* PRIVATE KEY-----/i,
  /\b(?:Bearer|DPoP)\s+[A-Za-z0-9._~+/=-]{16,}\b/i,
  /\b(?:sk|pk|rk|ghp|github_pat|xox[bap])-?[A-Za-z0-9_-]{16,}\b/i,
  /\bAIza[A-Za-z0-9_-]{20,}\b/,
  /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/,
] as const;

function normalizedKey(key: string): string {
  return key.replace(/[^a-z0-9]/gi, "").toLowerCase();
}

/** Reject secrets and local workspace bytes even when nested in arbitrary metadata. */
export function assertPortableDataSafe(value: unknown, path = "payload"): void {
  if (typeof value === "string") {
    if (SECRET_VALUE_PATTERNS.some((pattern) => pattern.test(value))) {
      throw new ContractValidationError(`Portable data contains credential-like text at ${path}.`);
    }
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((entry, index) => assertPortableDataSafe(entry, `${path}[${index}]`));
    return;
  }
  if (!value || typeof value !== "object") return;
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== "string") {
      throw new ContractValidationError(`Portable data may not contain non-string keys at ${path}.`);
    }
    const entry = (value as Record<string, unknown>)[key];
    const normalized = normalizedKey(key);
    if (FORBIDDEN_PORTABLE_KEY_PARTS.some((part) => normalized.includes(part))) {
      throw new ContractValidationError(`Portable data may not contain ${key} at ${path}.`);
    }
    assertPortableDataSafe(entry, `${path}.${key}`);
  }
}

export function validatePortableLearnerData(value: unknown): value is PortableLearnerData {
  if (!hasOnlyKeys(value, PORTABLE_DATA_KEYS)) return false;
  const data = value as Partial<PortableLearnerData>;
  const shapeIsValid = isContractTimestamp(data.generatedAt)
    && Array.isArray(data.sessions)
    && data.sessions.every(validateLearnerSession)
    && Array.isArray(data.artifacts) && data.artifacts.every(validateLearnerArtifact)
    && Array.isArray(data.goals) && data.goals.every(validateLearnerGoal)
    && Array.isArray(data.questionChecks) && data.questionChecks.every(validateLearnerQuestionCheck)
    && Array.isArray(data.quizResults) && data.quizResults.every(validateLearnerQuizResult)
    && Array.isArray(data.decks) && data.decks.every(validateFlashcardDeck)
    && Array.isArray(data.cardReviews) && data.cardReviews.every(validateCardReviewRecord)
    && validateLearnerProfile(data.learnerProfile);
  if (!shapeIsValid) return false;
  const portable = data as PortableLearnerData;

  const sessionsById = new Map(portable.sessions.map((session) => [session.id, session]));
  if (sessionsById.size !== portable.sessions.length) return false;
  for (const session of portable.sessions) {
    if (!session.parentSessionId) continue;
    const parent = sessionsById.get(session.parentSessionId);
    if (!parent || !session.forkedFromMessageId
      || !parent.messages.some((message) => message.id === session.forkedFromMessageId)) return false;
    const visited = new Set<string>();
    let cursor: LearnerSession | undefined = session;
    while (cursor?.parentSessionId) {
      if (visited.has(cursor.id)) return false;
      visited.add(cursor.id);
      cursor = sessionsById.get(cursor.parentSessionId);
    }
  }

  if (!hasUniqueIds(portable.artifacts) || !hasUniqueIds(portable.goals)
    || !hasUniqueIds(portable.questionChecks) || !hasUniqueIds(portable.quizResults)
    || !hasUniqueIds(portable.decks) || !hasUniqueIds(portable.cardReviews)) return false;
  const attachmentIds = portable.artifacts.flatMap((artifact) => artifact.attachment ? [artifact.attachment.id] : []);
  if (new Set(attachmentIds).size !== attachmentIds.length) return false;

  for (const artifact of portable.artifacts) {
    const source = artifact.sourceSessionId ? sessionsById.get(artifact.sourceSessionId) : undefined;
    if (artifact.sourceSessionId && !source) return false;
    if (artifact.sourceMessageId && (!source || !source.messages.some((message) => message.id === artifact.sourceMessageId))) return false;
  }
  if (portable.questionChecks.some((check) => check.sessionId && !sessionsById.has(check.sessionId))) return false;
  if (portable.quizResults.some((result) => result.sessionId && !sessionsById.has(result.sessionId))) return false;

  const cardsByDeckId = new Map(portable.decks.map((deck) => [deck.id, new Set(deck.cards.map((card) => card.id))]));
  return portable.cardReviews.every((review) => {
    const cards = cardsByDeckId.get(review.deckId);
    return !!cards && cards.has(review.cardId) && (!review.sessionId || sessionsById.has(review.sessionId));
  });
}

export function createPortableLearnerEnvelope(data: PortableLearnerData): PortableLearnerEnvelope {
  assertPortableDataSafe(data);
  if (!validatePortableLearnerData(data)) {
    throw new ContractValidationError("Portable learner data has an invalid shape.");
  }
  return {
    kind: PORTABLE_LEARNER_DATA_KIND,
    schemaVersion: LEARNER_CONTRACT_VERSION,
    payload: structuredClone(data),
  };
}

export function parsePortableLearnerEnvelope(value: unknown): PortableLearnerEnvelope {
  assertVersionedEnvelope<PortableLearnerData>(
    value,
    PORTABLE_LEARNER_DATA_KIND,
    LEARNER_CONTRACT_VERSION,
  );
  if (!validatePortableLearnerData(value.payload)) {
    throw new ContractValidationError("Portable learner data has an invalid shape.");
  }
  assertPortableDataSafe(value, "envelope");
  return {
    kind: PORTABLE_LEARNER_DATA_KIND,
    schemaVersion: LEARNER_CONTRACT_VERSION,
    payload: structuredClone(value.payload),
  };
}

export interface DatedRecord {
  id: string;
  updatedAt?: string;
  createdAt?: string;
}

export class MergeConflictError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MergeConflictError";
  }
}

function recordDate(record: DatedRecord): string {
  return record.updatedAt ?? record.createdAt ?? "";
}

function stableRecordJson(record: DatedRecord): string {
  const sort = (value: unknown): unknown => {
    if (Array.isArray(value)) return value.map(sort);
    if (!value || typeof value !== "object") return value;
    return Object.fromEntries(Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => codePointCompare(left, right))
      .map(([key, entry]) => [key, sort(entry)]));
  };
  return JSON.stringify(sort(record));
}

/** Newer records win. Concurrent equal-timestamp changes fail closed instead of silently discarding work. */
export function mergeDatedRecords<T extends DatedRecord>(...lists: ReadonlyArray<ReadonlyArray<T>>): T[] {
  const records = new Map<string, T>();
  for (const list of lists) {
    for (const candidate of list) {
      if (!isContractId(candidate.id) || !isContractTimestamp(recordDate(candidate))) {
        throw new ContractValidationError(`Cannot merge malformed record ${candidate.id}.`);
      }
      const current = records.get(candidate.id);
      if (current && recordDate(candidate) === recordDate(current)
        && stableRecordJson(candidate) !== stableRecordJson(current)) {
        throw new MergeConflictError(`Concurrent records conflict for ${candidate.id}.`);
      }
      if (!current
        || recordDate(candidate) > recordDate(current)
        || (recordDate(candidate) === recordDate(current) && stableRecordJson(candidate) === stableRecordJson(current))) {
        records.set(candidate.id, structuredClone(candidate));
      }
    }
  }
  return [...records.values()].sort((left, right) =>
    codePointCompare(recordDate(left), recordDate(right)) || codePointCompare(left.id, right.id));
}

function unionStrings(...lists: ReadonlyArray<ReadonlyArray<string>>): string[] {
  return [...new Set(lists.flat())].sort(codePointCompare);
}

function mergedProfile(left: LearnerProfile, right: LearnerProfile): LearnerProfile {
  return {
    topicsExplored: unionStrings(left.topicsExplored, right.topicsExplored),
    strengths: unionStrings(left.strengths, right.strengths),
    weaknesses: unionStrings(left.weaknesses, right.weaknesses),
    sessionsCount: Math.max(left.sessionsCount, right.sessionsCount),
    ...(left.lastSessionAt || right.lastSessionAt
      ? { lastSessionAt: [left.lastSessionAt, right.lastSessionAt].filter((value): value is string => !!value).sort(codePointCompare).at(-1) }
      : {}),
  };
}

export function mergePortableLearnerData(
  left: PortableLearnerData,
  right: PortableLearnerData,
): PortableLearnerData {
  if (!validatePortableLearnerData(left) || !validatePortableLearnerData(right)) {
    throw new ContractValidationError("Cannot merge invalid portable learner data.");
  }
  const generatedAt = left.generatedAt >= right.generatedAt ? left.generatedAt : right.generatedAt;
  const merged: PortableLearnerData = {
    generatedAt,
    sessions: mergeDatedRecords(left.sessions, right.sessions),
    artifacts: mergeDatedRecords(left.artifacts, right.artifacts),
    goals: mergeDatedRecords(left.goals, right.goals),
    questionChecks: mergeDatedRecords(left.questionChecks, right.questionChecks),
    quizResults: mergeDatedRecords(left.quizResults, right.quizResults),
    decks: mergeDatedRecords(left.decks, right.decks),
    cardReviews: mergeDatedRecords(left.cardReviews, right.cardReviews),
    learnerProfile: mergedProfile(left.learnerProfile, right.learnerProfile),
  };
  if (!validatePortableLearnerData(merged)) {
    throw new MergeConflictError("Merged learner data has dangling references or invalid lineage.");
  }
  return merged;
}
/** Dependency-free envelope used at every cross-surface persistence boundary. */
import { hasOnlyKeys, isRecord } from "./validation.js";

export interface VersionedEnvelope<T> {
  kind: string;
  schemaVersion: number;
  payload: T;
}

export const LEARNER_CONTRACT_VERSION = 1 as const;
export const PORTABLE_LEARNER_DATA_KIND = "keating-portable-learner-data" as const;
const ENVELOPE_KEYS = new Set(["kind", "schemaVersion", "payload"]);

export class ContractValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ContractValidationError";
  }
}

export function assertVersionedEnvelope<T>(
  value: unknown,
  kind: string,
  schemaVersion: number,
): asserts value is VersionedEnvelope<T> {
  if (!isRecord(value)) {
    throw new ContractValidationError("Contract envelope must be an object.");
  }
  if (!hasOnlyKeys(value, ENVELOPE_KEYS)) {
    throw new ContractValidationError("Contract envelope contains unknown fields.");
  }
  const envelope = value as Partial<VersionedEnvelope<T>>;
  if (envelope.kind !== kind) {
    throw new ContractValidationError(`Unsupported contract kind: ${String(envelope.kind)}.`);
  }
  if (envelope.schemaVersion !== schemaVersion) {
    throw new ContractValidationError(
      `Unsupported ${kind} schema version: ${String(envelope.schemaVersion)}.`,
    );
  }
  if (!("payload" in envelope)) {
    throw new ContractValidationError("Contract envelope has no payload.");
  }
}
import type { LearnerArtifact } from "./learning.js";
import { validateLearnerArtifact } from "./learning.js";
import { validateUiDocument, type UiDocument } from "./ui.js";
import { hasUniqueIds, isContractId, isContractTimestamp, isRecord } from "./validation.js";

export interface ToolCall {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  idempotencyKey: string;
}

export interface ToolResult {
  toolCallId: string;
  idempotencyKey: string;
  status: "success" | "error" | "retryable";
  text: string;
}

export type AgentStreamEvent =
  | { id: string; occurredAt: string; type: "text-delta"; turnId: string; sequence: number; text: string }
  | { id: string; occurredAt: string; type: "tool-call"; turnId: string; sequence: number; call: ToolCall }
  | { id: string; occurredAt: string; type: "tool-result"; turnId: string; sequence: number; result: ToolResult }
  | { id: string; occurredAt: string; type: "ui-document"; turnId: string; sequence: number; document: UiDocument }
  | { id: string; occurredAt: string; type: "artifact-emitted"; turnId: string; sequence: number; artifact: LearnerArtifact }
  | { id: string; occurredAt: string; type: "usage"; turnId: string; sequence: number; inputTokens: number; outputTokens: number }
  | { id: string; occurredAt: string; type: "error"; turnId: string; sequence: number; message: string; retryable: boolean }
  | { id: string; occurredAt: string; type: "completed"; turnId: string; sequence: number }
  | { id: string; occurredAt: string; type: "cancelled"; turnId: string; sequence: number };

export function validateToolCall(value: unknown): value is ToolCall {
  return isRecord(value) && isContractId(value.id) && typeof value.name === "string" && value.name.trim().length > 0
    && isRecord(value.arguments) && isContractId(value.idempotencyKey);
}

export function validateToolResult(value: unknown): value is ToolResult {
  return isRecord(value) && isContractId(value.toolCallId) && isContractId(value.idempotencyKey)
    && (value.status === "success" || value.status === "error" || value.status === "retryable")
    && typeof value.text === "string";
}

export function validateAgentStreamEvent(value: unknown): value is AgentStreamEvent {
  if (!isRecord(value) || !isContractId(value.id) || !isContractTimestamp(value.occurredAt)
    || !isContractId(value.turnId) || typeof value.sequence !== "number"
    || !Number.isSafeInteger(value.sequence) || value.sequence < 0) return false;
  switch (value.type) {
    case "text-delta": return typeof value.text === "string";
    case "tool-call": return validateToolCall(value.call);
    case "tool-result": return validateToolResult(value.result);
    case "ui-document": return validateUiDocument(value.document);
    case "artifact-emitted": return validateLearnerArtifact(value.artifact);
    case "usage": return typeof value.inputTokens === "number" && Number.isSafeInteger(value.inputTokens) && value.inputTokens >= 0
      && typeof value.outputTokens === "number" && Number.isSafeInteger(value.outputTokens) && value.outputTokens >= 0;
    case "error": return typeof value.message === "string" && typeof value.retryable === "boolean";
    case "completed": case "cancelled": return true;
    default: return false;
  }
}

/** A turn must have unique event/call/result identities and results can acknowledge only preceding calls. */
export function validateAgentStream(events: unknown): events is AgentStreamEvent[] {
  if (!Array.isArray(events) || !events.every(validateAgentStreamEvent) || !hasUniqueIds(events)) return false;
  const calls = new Map<string, ToolCall>();
  const callIdempotencyKeys = new Set<string>();
  const resultCallIds = new Set<string>();
  const resultIdempotencyKeys = new Set<string>();
  const sequences = new Set<number>();
  const turnId = events[0]?.turnId;
  let previousSequence = -1;
  let terminal = false;
  for (const event of events) {
    if (event.turnId !== turnId || terminal || sequences.has(event.sequence) || event.sequence <= previousSequence) return false;
    sequences.add(event.sequence);
    previousSequence = event.sequence;
    if (event.type === "tool-call") {
      if (calls.has(event.call.id) || callIdempotencyKeys.has(event.call.idempotencyKey)) return false;
      calls.set(event.call.id, event.call);
      callIdempotencyKeys.add(event.call.idempotencyKey);
    }
    if (event.type === "tool-result") {
      const call = calls.get(event.result.toolCallId);
      if (!call || call.idempotencyKey !== event.result.idempotencyKey
        || resultCallIds.has(event.result.toolCallId)
        || resultIdempotencyKeys.has(event.result.idempotencyKey)) return false;
      resultCallIds.add(event.result.toolCallId);
      resultIdempotencyKeys.add(event.result.idempotencyKey);
    }
    if (event.type === "completed" || event.type === "cancelled") terminal = true;
  }
  return true;
}

