} from "../src/nitro-runtime.js";
import {
	nitroEnvironment,
	resolveDesktopRuntimePaths,
} from "../src/runtime-paths.js";

describe("desktop Nitro runtime paths", () => {
	test("uses a read-only packaged resource and user-data-only mutable state", () => {
		const paths = resolveDesktopRuntimePaths({
			isPackaged: true,
			moduleDir: "/ignored/dist",
			resourcesPath: "/Applications/Keating.app/Contents/Resources",
			userData: "/Users/learner/Library/Application Support/Keating",
		});

		expect(paths.runtimeRoot).toBe("/Applications/Keating.app/Contents/Resources/nitro");
		expect(paths.serverEntry).toBe("/Applications/Keating.app/Contents/Resources/nitro/server/index.mjs");
		expect(paths.coursesStorageDir).toBe("/Users/learner/Library/Application Support/Keating/nitro/courses");
		expect(paths.coursesPearStorageDir).toBe("/Users/learner/Library/Application Support/Keating/nitro/courses-pear");
	});

	test("uses the staged dist/nitro tree while developing", () => {
		const paths = resolveDesktopRuntimePaths({
			isPackaged: false,
			moduleDir: "/work/desktop/dist",
			resourcesPath: "/unused",
			userData: "/tmp/keating-user",
		});

		expect(paths.runtimeRoot).toBe("/work/desktop/dist/nitro");
		expect(paths.serverEntry).toBe("/work/desktop/dist/nitro/server/index.mjs");
	});

	test("sets a loopback-only child environment without putting state in resources", () => {
		const paths = resolveDesktopRuntimePaths({
			isPackaged: false,
			moduleDir: "/work/desktop/dist",
			resourcesPath: "/unused",
			userData: "/tmp/keating-user",
		});
		const environment = nitroEnvironment(paths, 43123, { KEEP: "yes" });

		expect(environment).toMatchObject({
			KEEP: "yes",
			ELECTRON_RUN_AS_NODE: "1",
			NITRO_HOST: "127.0.0.1",
			NITRO_PORT: "43123",
			KEATING_COURSES_STORAGE_DIR: "/tmp/keating-user/nitro/courses",
			KEATING_COURSES_PEAR_STORAGE_DIR: "/tmp/keating-user/nitro/courses-pear",
		});
	});
});

describe("Nitro readiness", () => {
	test("retries bounded readiness probes until the local server is healthy", async () => {
		let clock = 0;
		let attempts = 0;
		await waitForNitroReady("http://127.0.0.1:43123", {
			timeoutMs: 30,
			intervalMs: 10,
			now: () => clock,
			sleep: async (milliseconds) => {
				clock += milliseconds;
			},
			fetchImpl: async () => ({ ok: ++attempts === 3 }),
		});
		expect(attempts).toBe(3);
	});

	test("fails after the bounded readiness deadline", async () => {
		let clock = 0;
		await expect(
			waitForNitroReady("http://127.0.0.1:43123", {
				timeoutMs: 20,
				intervalMs: 10,
				now: () => clock,
				sleep: async (milliseconds) => {
					clock += milliseconds;
				},
				fetchImpl: async () => ({ ok: false }),
			}),
		).rejects.toThrow("did not become ready within 20ms");
	});
});

describe("Nitro shutdown", () => {
	test("escalates only after graceful shutdown exceeds its deadline", async () => {
		const signals: string[] = [];
		const child = {
			exitCode: null,
			kill: (signal: string) => {
				signals.push(signal);
				return true;
			},
		} as unknown as ChildProcess;
		let waits = 0;
		await stopNitroChild(child, {
			timeoutMs: 1,
			waitForExit: async () => {
				if (++waits === 1) throw new Error("still running");
			},
		});
		expect(signals).toEqual(["SIGTERM", "SIGKILL"]);
	});
});

/**
 * IPC contract between the Electron renderer (preload bridge) and the main
 * process. Mirrors the request/response shape of
 * packages/browser-agent-runtime/src/rpc.ts. The desktop app implements the
 * main-side handlers (desktop/src/ipc.ts) and the preload bridge
 * (desktop/src/preload.ts) against these types — there is no `ipcRenderer`
 * passthrough.
 */

export const P2P_IPC_CHANNEL = "keating:p2p:rpc" as const;
export const P2P_EVENT_CHANNEL = "keating:p2p:event" as const;

/** Each method maps to a P2PStore-backed StorageBackend operation. */
export type P2PRpcMethod =
  | "get"
  | "set"
  | "delete"
  | "keys"
  | "getAllFromIndex"
  | "clear"
  | "has"
  | "batch"
  | "stats"
  | "quota"
  | "requestPersistence";

export interface P2PRpcRequest {
  id: string;
  method: P2PRpcMethod;
  params?: Record<string, unknown>;
}

export interface P2PRpcResponse<T = unknown> {
  id: string;
  ok: boolean;
  result?: T;
  error?: { message: string; code?: string };
}

/** Pushed from main → renderer when peer/replication state changes. */
export interface P2PEvent {
  type: "peerstats";
  payload: import("./types.js").PeerStats;
}
import type { P2PStore } from "./store.js";
import type { Mutation } from "./types.js";

/**
 * Minimal structural copy of web/src/types.ts `StorageBackend`. Duplicated here
 * (rather than imported) so this Node package has no dependency on the web app.
 * Keep the two in sync.
 */
export interface StorageBackendLike {
	get<T = unknown>(storeName: string, key: string): Promise<T | null>;
	set<T = unknown>(storeName: string, key: string, value: T): Promise<void>;
	delete(storeName: string, key: string): Promise<void>;
	keys(storeName: string, prefix?: string): Promise<string[]>;
	getAllFromIndex<T = unknown>(
		storeName: string,
		indexName: string,
		direction?: "asc" | "desc",
	): Promise<T[]>;
	clear(storeName: string): Promise<void>;
	has(storeName: string, key: string): Promise<boolean>;
	transaction<T>(
		storeNames: string[],
		mode: "readonly" | "readwrite",
		operation: (tx: {
			get<T2 = unknown>(storeName: string, key: string): Promise<T2 | null>;
			set<T2 = unknown>(storeName: string, key: string, value: T2): Promise<void>;
			delete(storeName: string, key: string): Promise<void>;
		}) => Promise<T>,
	): Promise<T>;
	getQuotaInfo(): Promise<{ usage: number; quota: number; percent: number }>;
	requestPersistence(): Promise<boolean>;
}

