					}
					return ok(id, await backend.getAllFromIndex(
						requireString(params, "storeName", MAX_STORE_NAME_LENGTH),
						requireString(params, "indexName", MAX_INDEX_NAME_LENGTH),
						direction ?? "asc",
					));
				}
				case "clear": {
					assertAllowedParams(params, ["storeName"]);
					await backend.clear(requireString(params, "storeName", MAX_STORE_NAME_LENGTH));
					return ok(id, undefined);
				}
