import { app, BrowserWindow, shell } from "electron";
import { randomBytes } from "node:crypto";
import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import {
	P2PStore,
	createP2PStorageBackend,
	type StorageBackendLike,
} from "@keating/p2p-core";
import { registerP2PIpc, type P2PBackendBridge } from "./ipc.js";
import {
	startPackagedNitro,
	type NitroRuntime,
} from "./nitro-runtime.js";
import { DesktopLifecycle } from "./lifecycle.js";
import { resolveDesktopRuntimePaths } from "./runtime-paths.js";
import {
	isSafeDevelopmentOrigin,
	isSafeExternalUrl,
	isTrustedAppNavigation,
	trustedOrigin,
} from "./security.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
let nitroRuntime: NitroRuntime | null = null;
let shuttingDown = false;
let windowOpening: Promise<void> | null = null;
const lifecycle = new DesktopLifecycle<P2PStore, NitroRuntime>();

/**
 * Load or create the per-user 32-byte secret that derives the swarm topic and
 * this device's writable core namespace.
 *
 * Resolution order:
 *  1. KEATING_USER_SECRET hex env var (lets you pair against a known seeder).
 *  2. A file at `${userData}/keating-user-secret.bin`. Created on first run
 *     with 32 bytes from sodium `crypto_randombytes_buf`.
 */
function loadUserSecret(): Uint8Array {
	const hex = process.env["KEATING_USER_SECRET"];
	if (hex && hex.trim().length > 0) {
		const trimmed = hex.trim();
		if (!/^[0-9a-fA-F]+$/.test(trimmed)) {
			throw new Error("KEATING_USER_SECRET must be hex-encoded");
		}
		const buf = Buffer.from(trimmed, "hex");
		if (buf.length !== 32) {
			throw new Error(
				`KEATING_USER_SECRET must be 32 bytes (got ${buf.length})`,
			);
		}
		return new Uint8Array(buf);
	}

	const userData = app.getPath("userData");
	const secretPath = join(userData, "keating-user-secret.bin");
	if (existsSync(secretPath)) {
		const raw = readFileSync(secretPath);
		if (raw.length !== 32) {
			throw new Error(
				`keating-user-secret.bin must be 32 bytes (got ${raw.length})`,
			);
		}
		return new Uint8Array(raw);
	}

	// First run: ensure userData exists, then generate and persist.
	try {
		mkdirSync(userData, { recursive: true });
	} catch {
		// ignore — likely already exists
	}
	const out = randomBytes(32);
	writeFileSync(secretPath, out);
	return out;
}

function installNavigationPolicy(window: BrowserWindow, appOrigin: string): void {
	const denyOrExternalize = (event: { preventDefault(): void }, url: string) => {
		if (isTrustedAppNavigation(url, appOrigin)) return;
		event.preventDefault();
		if (isSafeExternalUrl(url)) void shell.openExternal(url).catch(() => {});
	};
	window.webContents.on("will-navigate", denyOrExternalize);
	window.webContents.on("will-redirect", denyOrExternalize);
	window.webContents.setWindowOpenHandler(({ url }) => {
		if (isSafeExternalUrl(url)) void shell.openExternal(url).catch(() => {});
		return { action: "deny" };
	});
}

async function appOrigin(): Promise<string> {
	const devServer = process.env["KEATING_DEV_SERVER"];
	if (devServer) {
		if (!isSafeDevelopmentOrigin(devServer)) {
			throw new Error("KEATING_DEV_SERVER must be a loopback http origin.");
		}
		const origin = trustedOrigin(devServer);
		if (!origin) throw new Error("KEATING_DEV_SERVER has no valid origin.");
		return origin;
	}
	return (await ensurePackagedNitro()).origin;
}

async function getP2PStore(): Promise<P2PStore> {
	return lifecycle.openStore(async () => {
		const userSecret = loadUserSecret();
		return P2PStore.open({
			storageDir: join(app.getPath("userData"), "p2p"),
			userSecret,
			label: `desktop:${process.platform}`,
		});
	});
}

async function createWindow(): Promise<void> {
	let window: BrowserWindow | null = null;
	try {
		const origin = await appOrigin();
		const store = await getP2PStore();
		window = new BrowserWindow({
			width: 1200,
			height: 800,
			webPreferences: {
				preload: join(__dirname, "preload.js"),
				contextIsolation: true,
				nodeIntegration: false,
				sandbox: true,
			},
		});

		const backend: StorageBackendLike = createP2PStorageBackend(store);
		const bridge: P2PBackendBridge = {
			...backend,
			batch: (mutations) => store.batch(mutations),
			stats: () => store.stats(),
		};
		lifecycle.setRendererCleanup(registerP2PIpc(window, bridge, { appOrigin: origin }));
		installNavigationPolicy(window, origin);
		await window.loadURL(new URL("/chat", origin).toString());
	} catch (error) {
		if (window && !window.isDestroyed()) window.destroy();
		await shutdownDesktop();
		throw error;
	}
}

function openWindow(): Promise<void> {
	if (windowOpening) return windowOpening;
	windowOpening = createWindow().finally(() => {
		windowOpening = null;
	});
	return windowOpening;
}

async function ensurePackagedNitro(): Promise<NitroRuntime> {
	if (nitroRuntime) return nitroRuntime;

	const paths = resolveDesktopRuntimePaths({
		isPackaged: app.isPackaged,
		moduleDir: __dirname,
		resourcesPath: process.resourcesPath,
		userData: app.getPath("userData"),
	});
	nitroRuntime = await startPackagedNitro(paths);
	lifecycle.setNitro(nitroRuntime);
	return nitroRuntime;
}

async function shutdownDesktop(): Promise<void> {
	await lifecycle.shutdown();
	nitroRuntime = null;
}

app.whenReady()
	.then(async () => {
		await openWindow();
		app.on("activate", () => {
			if (BrowserWindow.getAllWindows().length === 0) {
				void openWindow().catch((error) => {
					console.error("Keating desktop failed to reactivate:", error);
					app.quit();
				});
			}
		});
	})
	.catch((error) => {
		console.error("Keating desktop failed to start:", error);
		void shutdownDesktop().finally(() => app.quit());
	});

app.on("before-quit", (event) => {
	if (shuttingDown) return;
	shuttingDown = true;
	event.preventDefault();
	void shutdownDesktop().finally(() => app.quit());
});

app.on("window-all-closed", () => {
	if (process.platform !== "darwin") app.quit();
});
import { ipcMain, type BrowserWindow } from "electron";
import {
	P2P_IPC_CHANNEL,
	P2P_EVENT_CHANNEL,
	type P2PRpcRequest,
	type P2PRpcResponse,
	type P2PEvent,
	type StorageBackendLike,
	type Mutation,
	type PeerStats,
} from "@keating/p2p-core";
import {
	assertAllowedParams,
	assertBoundedName,
	assertBoundedSerializablePayload,
	assertKnownRpcMethod,
	assertPlainParams,
	createRequestIdTracker,
	IpcValidationError,
	isTrustedAppNavigation,
	MAX_INDEX_NAME_LENGTH,
	MAX_KEY_LENGTH,
	MAX_MUTATION_COUNT,
	MAX_RPC_ID_LENGTH,
	MAX_STORE_NAME_LENGTH,
	sanitizeIpcError,
} from "./security.js";

export interface P2PBackendBridge extends StorageBackendLike {
	batch(mutations: Mutation[]): Promise<void>;
	stats(): PeerStats;
}

export interface P2PIpcOptions {
	/** Exact local Nitro or explicitly configured dev origin allowed to use the preload bridge. */
	appOrigin: string;
}

interface ParsedRequest {
	id: string;
	method: P2PRpcRequest["method"];
	params: Record<string, unknown> | undefined;
}

let activeCleanup: (() => void) | null = null;

function fail(id: string, message: string): P2PRpcResponse {
	return { id, ok: false, error: { message } };
}

function ok<T>(id: string, result: T): P2PRpcResponse<T> {
	return { id, ok: true, result };
}

function parseRequest(value: unknown): ParsedRequest {
	if (!value || typeof value !== "object" || Array.isArray(value)) {
		throw new IpcValidationError("RPC request is invalid.");
	}
	const request = value as Record<string, unknown>;
	const id = assertBoundedName(request["id"], "RPC id", MAX_RPC_ID_LENGTH);
	const method = assertKnownRpcMethod(request["method"]) as P2PRpcRequest["method"];
	const params = assertPlainParams(request["params"]);
	assertBoundedSerializablePayload(params ?? null);
	return { id, method, params };
}

function requireString(
	params: Record<string, unknown> | undefined,
	key: string,
	limit = MAX_KEY_LENGTH,
): string {
	return assertBoundedName(params?.[key], `RPC ${key}`, limit);
}

function requireOptionalString(
	params: Record<string, unknown> | undefined,
	key: string,
	limit = MAX_KEY_LENGTH,
): string | undefined {
	if (params === undefined || !(key in params) || params[key] === undefined || params[key] === null) return undefined;
	return assertBoundedName(params[key], `RPC ${key}`, limit);
}

function requireStoreKeys(params: Record<string, unknown> | undefined): { storeName: string; key: string } {
	assertAllowedParams(params, ["storeName", "key"]);
	return {
		storeName: requireString(params, "storeName", MAX_STORE_NAME_LENGTH),
		key: requireString(params, "key"),
	};
}

function requireValue(params: Record<string, unknown> | undefined): unknown {
	if (!params || !("value" in params)) throw new IpcValidationError("RPC value is required.");
	assertBoundedSerializablePayload(params["value"]);
	return params["value"];
}

function parseMutations(params: Record<string, unknown> | undefined): Mutation[] {
	assertAllowedParams(params, ["mutations"]);
	const raw = params?.["mutations"];
	if (!Array.isArray(raw) || raw.length > MAX_MUTATION_COUNT) {
		throw new IpcValidationError("RPC mutations are invalid.");
	}
	return raw.map((mutation, index) => {
		if (!mutation || typeof mutation !== "object" || Array.isArray(mutation)) {
			throw new IpcValidationError(`RPC mutation ${index} is invalid.`);
		}
		const candidate = mutation as Record<string, unknown>;
		if (candidate["type"] === "put") {
			assertAllowedParams(candidate, ["type", "store", "key", "value"]);
			if (!("value" in candidate)) throw new IpcValidationError(`RPC mutation ${index} needs a value.`);
			assertBoundedSerializablePayload(candidate["value"]);
			return {
				type: "put" as const,
				store: assertBoundedName(candidate["store"], "RPC store", MAX_STORE_NAME_LENGTH),
				key: assertBoundedName(candidate["key"], "RPC key", MAX_KEY_LENGTH),
				value: candidate["value"],
			};
		}
		if (candidate["type"] === "del") {
			assertAllowedParams(candidate, ["type", "store", "key"]);
			return {
				type: "del" as const,
				store: assertBoundedName(candidate["store"], "RPC store", MAX_STORE_NAME_LENGTH),
				key: assertBoundedName(candidate["key"], "RPC key", MAX_KEY_LENGTH),
			};
		}
		throw new IpcValidationError(`RPC mutation ${index} has an invalid type.`);
	});
}

function senderIsAuthorized(
	event: { sender: { id: number; getURL(): string }; senderFrame?: { url: string } | null },
	window: BrowserWindow,
	appOrigin: string,
): boolean {
	if (event.sender.id !== window.webContents.id) return false;
	return isTrustedAppNavigation(event.senderFrame?.url ?? event.sender.getURL(), appOrigin);
}

/**
 * Register one renderer-scoped handler. IPC is a process-global Electron API,
 * so a replacement tears down the former window before installing the next.
 */
export function registerP2PIpc(
	window: BrowserWindow,
	backend: P2PBackendBridge,
	options: P2PIpcOptions,
): () => void {
	activeCleanup?.();
	const requestIds = createRequestIdTracker();
	let stopped = false;
	const handle = async (
		event: { sender: { id: number; getURL(): string }; senderFrame?: { url: string } | null },
		req: unknown,
	): Promise<P2PRpcResponse> => {
		if (stopped || !senderIsAuthorized(event, window, options.appOrigin)) {
			return fail("", "IPC sender is not authorized.");
		}

		let request: ParsedRequest | undefined;
		try {
			request = parseRequest(req);
			if (!requestIds.claim(request.id)) return fail(request.id, "RPC id has already been used.");
			const { id, method, params } = request;
			switch (method) {
				case "get": {
					const { storeName, key } = requireStoreKeys(params);
					return ok(id, await backend.get(storeName, key));
				}
				case "set": {
					assertAllowedParams(params, ["storeName", "key", "value"]);
					const storeName = requireString(params, "storeName", MAX_STORE_NAME_LENGTH);
					const key = requireString(params, "key");
					await backend.set(storeName, key, requireValue(params));
					return ok(id, undefined);
				}
				case "delete": {
					const { storeName, key } = requireStoreKeys(params);
					await backend.delete(storeName, key);
					return ok(id, undefined);
				}
				case "keys": {
					assertAllowedParams(params, ["storeName", "prefix"]);
					return ok(id, await backend.keys(
						requireString(params, "storeName", MAX_STORE_NAME_LENGTH),
						requireOptionalString(params, "prefix"),
					));
				}
				case "getAllFromIndex": {
					assertAllowedParams(params, ["storeName", "indexName", "direction"]);
					const direction = params?.["direction"];
					if (direction !== undefined && direction !== "asc" && direction !== "desc") {
						throw new IpcValidationError("RPC direction is invalid.");
					}
					return ok(id, await backend.getAllFromIndex(
						requireString(params, "storeName", MAX_STORE_NAME_LENGTH),
						requireString(params, "indexName", MAX_INDEX_NAME_LENGTH),
						direction ?? "asc",
					));
				}
				case "clear": {
					assertAllowedParams(params, ["storeName"]);
					await backend.clear(requireString(params, "storeName", MAX_STORE_NAME_LENGTH));
					return ok(id, undefined);
				}
				case "has": {
					const { storeName, key } = requireStoreKeys(params);
					return ok(id, await backend.has(storeName, key));
				}
				case "batch": {
					await backend.batch(parseMutations(params));
					return ok(id, undefined);
				}
				case "stats":
					assertAllowedParams(params, []);
					return ok(id, backend.stats());
				case "quota":
					assertAllowedParams(params, []);
					return ok(id, await backend.getQuotaInfo());
				case "requestPersistence":
					assertAllowedParams(params, []);
					return ok(id, await backend.requestPersistence());
			}
		} catch (error) {
			return fail(request?.id ?? "", sanitizeIpcError(error));
		}
	};

	ipcMain.handle(P2P_IPC_CHANNEL, handle);
	const send = () => {
		if (stopped || window.isDestroyed()) return;
		try {
			const evt: P2PEvent = { type: "peerstats", payload: backend.stats() };
			window.webContents.send(P2P_EVENT_CHANNEL, evt);
		} catch {
			// The store may be closing; do not expose a native error to the renderer.
		}
	};
	const interval = setInterval(send, 2_000);
	send();

	const cleanup = () => {
		if (stopped) return;
		stopped = true;
		clearInterval(interval);
		window.removeListener("closed", cleanup);
		if (activeCleanup === cleanup) {
			activeCleanup = null;
			ipcMain.removeHandler(P2P_IPC_CHANNEL);
		}
	};
	activeCleanup = cleanup;
	window.once("closed", cleanup);
	return cleanup;
}

