    18	  target_version INTEGER NOT NULL CHECK (target_version >= source_version),
    19	  digest TEXT NOT NULL CHECK (length(digest) = 64 AND digest NOT GLOB '*[^a-f0-9]*'),
    20	  phase TEXT NOT NULL CHECK (phase IN ('prepared', 'copied', 'verified', 'completed')),
    21	  created_at TEXT NOT NULL,
    22	  updated_at TEXT NOT NULL,
    23	  completed_at TEXT,
    24	  CHECK (
    25	    (phase = 'completed' AND completed_at IS NOT NULL)
    26	    OR (phase <> 'completed' AND completed_at IS NULL)
    27	  )
    28	);
    29	CREATE INDEX IF NOT EXISTS migration_journal_phase_idx
