    43	/**
    44	 * Applies only the repository foundation. Learner-record tables are added by
    45	 * subsequent versioned migrations, not implicitly by the first opener.
    46	 */
    47	export async function initializeRepositorySchema(database: AsyncSqlDatabase): Promise<void> {
    48	  await database.execAsync("PRAGMA foreign_keys = ON;");
    49	  await database.execAsync("PRAGMA journal_mode = WAL;");
    50	  await withExclusiveTransaction(database, async (transaction) => {
    51	    await transaction.execAsync(CREATE_FOUNDATION_SQL);
    52	    await ensureSchemaMetadata(transaction);
    53	  });
    54	}
    55	
    56	async function ensureSchemaMetadata(transaction: AsyncSqlExecutor): Promise<void> {
    57	  const existing = await transaction.getFirstAsync<MetaRow>(
    58	    "SELECT value FROM repository_meta WHERE key = ?;",
    59	    "schema_version",
    60	  );
    61	  if (!existing) {
    62	    await transaction.runAsync(
    63	      "INSERT INTO repository_meta (key, value) VALUES (?, ?);",
    64	      "schema_version",
    65	      String(LEARNER_REPOSITORY_SCHEMA_VERSION),
    66	    );
    67	    return;
    68	  }
    69	
    70	  const stored = parseStoredSchemaVersion(existing.value);
    71	  if (stored === null) throw new Error("Learner repository schema metadata is invalid.");
    72	  if (stored > LEARNER_REPOSITORY_SCHEMA_VERSION) {
    73	    throw new Error("Learner repository was created by a newer app version.");
    74	  }
    75	  if (stored < LEARNER_REPOSITORY_SCHEMA_VERSION) {
    76	    throw new Error("Learner repository schema migration is required.");
    77	  }
    78	}
