   301	interface ActionTarget {
   302	  node: UiDocumentNode;
   303	  question?: UiQuestion;
   304	}
   305	
   306	function findActionTarget(document: UiDocument, nodeId: string): ActionTarget | undefined {
   307	  for (const node of document.nodes) {
   308	    if (node.id === nodeId) return { node };
   309	    if (node.type === "quiz") {
   310	      const question = node.questions.find((candidate) => candidate.id === nodeId);
   311	      if (question) return { node, question };
   312	    }
   313	  }
   314	  return undefined;
   315	}
   316	
   317	/** Validates that an action is applicable to this exact document snapshot. */
   318	export function validateUiActionAgainstDocument(action: unknown, document: unknown): action is UiAction {
   319	  if (!validateUiAction(action) || !validateUiDocument(document)) return false;
   320	  if (action.documentId !== document.id || action.documentRevision !== document.revision) return false;
   321	  if (action.type === "retry") return document.lifecycle === "failed" || document.lifecycle === "cancelled";
   322	  if (document.lifecycle !== "ready") return false;
   323	  const target = findActionTarget(document, action.nodeId);
   324	  if (!target) return false;
   325	  const question = target.node.type === "question" ? target.node : target.question;
   326	  switch (action.type) {
   327	    case "submit-answer": return !!question && question.choices === undefined && typeof action.answer === "string";
   328	    case "choose-option": {
   329	      if (!question?.choices || question.choices.length === 0) return false;
   330	      if (!question.multiSelect && action.optionIds.length !== 1) return false;
   331	      const allowed = new Set(question.choices.map((choice) => choice.id));
   332	      return action.optionIds.every((id) => allowed.has(id));
   333	    }
   334	    case "complete-goal-step": return target.node.type === "goal" && target.node.steps.some((step) => step.id === action.stepId && step.status !== "done");
   335	    case "rate-card": return target.node.type === "deck" && target.node.cards.some((card) => card.id === action.cardId);
   336	    case "save-artifact": return target.node.type === "study-plan" || target.node.type === "artifact" || target.node.type === "image" || target.node.type === "media";
   337	    case "open-handoff": return target.node.type === "handoff";
   338	  }
   339	}
   340	
   341	export function validateUiActionResult(value: unknown): value is UiActionResult {
   342	  if (!hasOnlyKeys(value, RESULT_KEYS)) return false;
   343	  const result = value as UiActionResult;
   344	  if (result.schemaVersion !== UI_CONTRACT_VERSION || !isContractId(result.documentId) || !validRevision(result.sourceRevision)
   345	    || !isContractId(result.actionIdempotencyKey) || !(result.status === "accepted" || result.status === "completed" || result.status === "rejected" || result.status === "retryable")
   346	    || !LIFECYCLES.has(result.documentLifecycle) || (result.message !== undefined && !boundedString(result.message, 4096, true))) return false;
   347	  if (result.status === "retryable") {
   348	    const retryAfterMs = result.retryAfterMs;
   349	    if (typeof retryAfterMs !== "number" || !Number.isSafeInteger(retryAfterMs) || retryAfterMs < 0 || result.resultingDocument !== undefined) return false;
   350	  } else if (result.retryAfterMs !== undefined) return false;
   351	  if (result.status === "completed") {
   352	    const document = result.resultingDocument;
   353	    return !!document && validateUiDocument(document) && document.id === result.documentId
   354	      && document.revision > result.sourceRevision && document.lifecycle === result.documentLifecycle;
   355	  }
   356	  return result.resultingDocument === undefined;
   357	}
   358	
   359	/** A result is only applicable to the action/document revision it acknowledges. */
   360	export function validateUiActionCorrelation(action: UiAction, result: UiActionResult, sourceDocument?: UiDocument): boolean {
   361	  if (!validateUiAction(action) || !validateUiActionResult(result)
   362	    || action.schemaVersion !== result.schemaVersion || action.documentId !== result.documentId
   363	    || action.documentRevision !== result.sourceRevision || action.idempotencyKey !== result.actionIdempotencyKey) return false;
   364	  if (!sourceDocument) return true;
   365	  if (!validateUiActionAgainstDocument(action, sourceDocument)) return false;
   366	  if (result.status === "completed") return result.resultingDocument?.id === sourceDocument.id
   367	    && result.resultingDocument.revision > sourceDocument.revision;
   368	  return result.documentLifecycle === sourceDocument.lifecycle;
   369	}
   370	
   371	/** Stable representation used to reject accidental reuse of an idempotency key. */
   372	export function canonicalUiAction(action: UiAction): string {
   373	  const sort = (value: unknown): unknown => {
   374	    if (Array.isArray(value)) return value.map(sort);
   375	    if (!isRecord(value)) return value;
   376	    return Object.fromEntries(Object.entries(value).sort(([left], [right]) => codePointCompare(left, right)).map(([key, child]) => [key, sort(child)]));
   377	  };
   378	  return JSON.stringify(sort(action));
   379	}
   380	
   381	export function validateUiActionReceipt(value: unknown): value is UiActionReceipt {
   382	  if (!hasOnlyKeys(value, RECEIPT_KEYS)) return false;
   383	  const receipt = value as UiActionReceipt;
   384	  if (receipt.schemaVersion !== UI_CONTRACT_VERSION || !validateUiAction(receipt.action)
   385	    || receipt.actionFingerprint !== canonicalUiAction(receipt.action) || !RECEIPT_STATES.has(receipt.state)
   386	    || !isContractTimestamp(receipt.createdAt) || !isContractTimestamp(receipt.updatedAt) || compareContractTimestamps(receipt.updatedAt, receipt.createdAt) < 0) return false;
   387	  if (receipt.state === "pending") return receipt.result === undefined;
   388	  return !!receipt.result && validateUiActionResult(receipt.result)
   389	    && receipt.result.status === receipt.state && validateUiActionCorrelation(receipt.action, receipt.result);
   390	}
   391	
   392	export function validateUiActionJournal(value: unknown): value is UiActionJournal {
   393	  if (!hasOnlyKeys(value, JOURNAL_KEYS)) return false;
   394	  const journal = value as UiActionJournal;
   395	  if (journal.kind !== UI_ACTION_JOURNAL_KIND || journal.schemaVersion !== UI_CONTRACT_VERSION || !isContractId(journal.documentId)
   396	    || !boundedArray(journal.receipts, MAX_JOURNAL_RECEIPTS) || !journal.receipts.every(validateUiActionReceipt)) return false;
   397	  const keys = new Map<string, string>();
   398	  for (const receipt of journal.receipts) {
   399	    if (receipt.action.documentId !== journal.documentId) return false;
   400	    const prior = keys.get(receipt.action.idempotencyKey);
   401	    if (prior !== undefined) return false;
   402	    keys.set(receipt.action.idempotencyKey, receipt.actionFingerprint);
   403	  }
   404	  return true;
   405	}
   406	
   407	/** Returns a replayable receipt or fails closed when a key names a different action. */
   408	export function receiptForUiAction(journal: UiActionJournal, action: UiAction): UiActionReceipt | undefined {
   409	  if (!validateUiActionJournal(journal)) throw new UiActionReplayConflictError("Cannot replay an invalid UI action journal.");
   410	  if (!validateUiAction(action) || journal.documentId !== action.documentId) throw new UiActionReplayConflictError("Action does not belong to this UI action journal.");
   411	  const receipt = journal.receipts.find((candidate) => candidate.action.idempotencyKey === action.idempotencyKey);
   412	  if (!receipt) return undefined;
   413	  if (receipt.actionFingerprint !== canonicalUiAction(action)) {
   414	    throw new UiActionReplayConflictError(`Idempotency key ${action.idempotencyKey} names a different action.`);
   415	  }
   416	  return receipt;
   417	}

